function requireSecret(env: NodeJS.ProcessEnv, name: string): string {
  const value = env[name];
  if (value && value.length >= 32) return value;
  if (env.NODE_ENV !== 'production' && !value) {
    console.warn(`[config] ${name} is not set; using an insecure development default`);
    return 'dev-only-secret-do-not-use-in-production-00';
  }
  throw new Error(`${name} must be set and at least 32 characters long`);
}

